nta.declaration:
// One HypaV3 summarization request on a phone that gets locked (src/ts/process/memory/hypav3.ts summarize, retry.ts withRetry).
// Time unit: tenths of a second.
const int DMIN = 100;     // a summary request takes at least 10 s ...
const int D = 600;        // ... and at most 60 s (grok behind 9router)
const int N = 4;          // attempts: withRetry makes 1 + (number of delays) attempts
const int BD[3] = {15, 40, 100};   // waits before retry 1, 2, ...
const int LMAX = 6000;    // a lock lasts at most 600 s
const int LOCKS = 3;    // how many times the screen is locked during this one summary

int[0,10] nl = 0;
clock c;                  // how long the screen has been locked
clock r;                  // age of the current request
clock b;                  // backoff timer
broadcast chan lock, unlock;

nta.system:
phone = Phone();
summ = Summ();
system phone, summ;
